import (
	"bufio"
	"fmt"
	"os"
)

var (
	mod int64 = 998244353
	MOD int64 = 1000000007
)

func main() {
	sc := NewScanner(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	n, _ := sc.NextInt()
	if n%2 == 0 {
		fmt.Fprintln(out, "white")
		fmt.Fprint(out, "1 2")
	} else {
		fmt.Fprint(out, "black")
	}
}

type Scanner struct {
	scanner *bufio.Scanner
}

func NewScanner(r *os.File) *Scanner {
	sc := bufio.NewScanner(r)
	sc.Split(bufio.ScanWords)
	return &Scanner{scanner: sc}
}

func (s *Scanner) Next() (string, error) {
	if !s.scanner.Scan() {
		return "", s.scanner.Err()
	}
	return s.scanner.Text(), nil
}

func (s *Scanner) NextInt() (int, error) {
	token, err := s.Next()
	if err != nil {
		return 0, err
	}
	var val int
	_, err = fmt.Sscan(token, &val)
	return val, err
}

func (s *Scanner) NextInt64() (int64, error) {
	token, err := s.Next()
	if err != nil {
		return 0, err
	}
	var val int64
	_, err = fmt.Sscan(token, &val)
	return val, err
}

func (s *Scanner) NextLine() (string, error) {
	reader := bufio.NewReader(os.Stdin)
	line, err := reader.ReadString('\n')
	return line, err
}

